from gtlib import *
L=lambda u,t: f'<a href="{u}">{t}</a>'
GP=L('/ganesha/foundations/ganapatya/','the Gāṇapatya tradition')
YA=L('/ganesha/forms/yuga-avatars/','the four yuga avatāras')
SRC_ASH=('Temple facts:','Wikipedia, “Ashtavinayaka” and the article on each temple; temple and district information, as summarised in our earlier guides; Anne Feldhaus on Morgaon’s dating.')
# ---------- OVERVIEW ----------
i=0
COV=covart('Eight small Gaṇeśa shrines in a ring around a city, with a peacock and a mouse',''.join(g(220+150*__import__('math').cos(k*0.785),105+70*__import__('math').sin(k*0.785),.5,palace()) for k in range(8))+g(220,120,.7,ganesha())+g(60,190,.9,mouse()))
pp=[foreword(i,['Eight Gaṇeśas stand in a ring round Pune: on the Deccan plateau, in the folds of the Sahyādri and down on the Konkan. Pilgrims visit them in a set order, beginning and ending at Morgaon, and call the circuit the <b>Aṣṭavināyaka</b>, “the eight Vināyakas”.','Every image is believed to be <b>svayambhū</b>, risen by itself from the earth, and every temple keeps its own story from the Gaṇeśa and Mudgala Purāṇas. This overview gives the order, the map, the eight legends in brief, the saints and Peshwas who shaped the temples, and how the pilgrimage is made. Each temple then has its own guide.'],[('z','Why eight?'),('b','Eight is the number of directions and of Gaṇeśa’s great forms in the Mudgala Purāṇa, Zappy. And eight makes a perfect circle round Pune.')]),
 glance([('What','Eight Gaṇeśa temples in Maharashtra'),('Order','Morgaon, Siddhaṭek, Pālī, Mahaḍ, Theūr, Leṇyādri, Ojhar, Rāñjaṇgāv, then Morgaon again'),('Where','Five in Pune district, two in Raigad, one in Ahilyanagar'),('Images','All believed svayambhū, self-manifested'),('Texts','Gaṇeśa Purāṇa and Mudgala Purāṇa legends'),('Saint','Moraya Gosāvī and his Chinchwad line'),('Patrons','The Peshwas of Pune, 18th century'),('Time','About three days by road')],amap()),
 reading('map','THE RING ROUND PUNE','Plateau, ghats and Konkan',amap(),['<b>Five on the plateau.</b> Morgaon, Theūr, Rāñjaṇgāv, Leṇyādri and Ojhar lie on the Deccan around Pune, by the rivers Karhā, Bhīmā, Mula–Mutha and Kukaḍī.','<b>One across the Bhīmā.</b> Siddhaṭek sits on the north bank of the Bhīmā in Ahilyanagar district.','<b>Two in the Konkan.</b> Pālī and Mahaḍ lie below the ghats in Raigad district, reached down the Khandala–Khopoli road.','<b>Rivers and hills.</b> Almost every temple stands by a river or a hill: a reminder that Gaṇeśa, son of the mountain’s daughter, is worshipped where land and water meet.'],[('z','So I drive round Pune in a circle?'),('b','A rough circle, Zappy, with a long dip down to the coast and back.')],'Plateau, ghats and <b>coast</b>.'),
 cards('order','THE EIGHT IN ORDER','The pilgrimage sequence',amap(),[('1','Morgaon · Mayūreśvara','Gaṇeśa on a peacock, first and last. '+L('/ganesha/temples/morgaon/','Guide')),('2','Siddhaṭek · Siddhivināyaka','The right-turned trunk, by the Bhīmā. '+L('/ganesha/temples/siddhatek/','Guide')),('3','Pālī · Ballāḷeśvara','Named after a child devotee. '+L('/ganesha/temples/pali/','Guide')),('4','Mahaḍ · Varadavināyaka','The boon-giver by the pond. '+L('/ganesha/temples/mahad/','Guide')),('5','Theūr · Cintāmaṇi','The wish-jewel, closest to Pune. '+L('/ganesha/temples/theur/','Guide')),('6','Leṇyādri · Girijātmaja','In a Buddhist cave, up 283 steps. '+L('/ganesha/temples/lenyadri/','Guide')),('7','Ojhar · Vighneśvara','Lord of obstacles, golden dome. '+L('/ganesha/temples/ozar/','Guide')),('8','Rāñjaṇgāv · Mahāgaṇapati','Śiva’s Gaṇeśa, then back to Morgaon. '+L('/ganesha/temples/ranjangaon/','Guide'))],[('z','Is the order fixed?'),('b','Tradition fixes it, Zappy; roads sometimes bend it. Morgaon first and last is the rule most keep.')],'Eight Gaṇeśas, <b>one circle</b>.'),
 reading('svayambhu','SVAYAMBHŪ','Images no hand carved',gimg('A rough Gaṇeśa image coated in orange sindūr between lamps','orange sindūr, jewelled eyes'),['<b>The belief.</b> Each of the eight images is held to have appeared by itself: Gaṇeśa’s form revealed in the stone, found by devotees rather than made by sculptors.','<b>The look.</b> Many are rough stones thickly coated in orange <b>sindūr</b>, with eyes and navel set with diamonds or other jewels that catch the lamplight.','<b>Trunks.</b> Most turn to the left; Siddhaṭek’s turns right, the only one among the eight. Right-turned images are believed powerful and to need strict worship.','<b>An honest note.</b> Mahaḍ’s image is said to have been found in a lake in 1690, which sits awkwardly with the svayambhū claim. Belief and history do not always line up neatly.'],[('z','Nobody carved them?'),('b','That’s the belief, Zappy. The stone itself took his form.')],'Found, <b>not made</b>.'),
 cards('legends','EIGHT LEGENDS','A small Gaṇeśa Purāṇa you can drive round',svg(560,130,'Eight small scenes in a row: peacock, Viṣṇu, child, sage, jewel, cave, demon, Śiva',f'<rect width="560" height="130" fill="#fff3cf"/>'+''.join(g(35+k*70,115,.55,x) for k,x in enumerate([peacock() if False else bird('#2a6ab8'),vishnu(),child(),sage(),coins(),mountain('#8a7a5a',False),demon(),shiva()]))),[('🦚','Morgaon','Gaṇeśa rides a peacock to slay Sindhu, who had swallowed the nectar of immortality.'),('🌀','Siddhaṭek','Viṣṇu, losing to Madhu and Kaiṭabha, wins siddhi here from Gaṇeśa.'),('👦','Pālī','The boy Ballāḷa, beaten and bound for his devotion, is freed by Gaṇeśa.'),('🧘','Mahaḍ','The sage Gṛtsamada’s penance; Gaṇeśa stays as the boon-giver.'),('💎','Theūr','Gaṇeśa wins back the wish-jewel Cintāmaṇi for the sage Kapila.'),('⛰️','Leṇyādri','Pārvatī’s twelve-year penance for a son; Gaṇeśa’s childhood.'),('👹','Ojhar','The demon of obstacles, Vighnāsura, surrenders and joins his name to Gaṇeśa’s.'),('🔱','Rāñjaṇgāv','Śiva worships Gaṇeśa before destroying the three cities of Tripura.')],[('z','Every temple has a story?'),('b','Every one, Zappy. And three of them teach the same lesson: even the great gods begin with Gaṇeśa.')],'Eight stories, <b>one lesson</b>.'),
 reading('history','SAINTS AND PESHWAS','How the circuit took shape',tscene('A walled stone temple with lamp towers and a saffron flag',g(420,60,.8,flag())),['<b>Old claims.</b> The Purāṇas and temple traditions make the shrines very ancient. The buildings we see are mostly much later.','<b>Moraya Gosāvī.</b> The great Gāṇapatya saint of the 16th–17th centuries worshipped at Morgaon and Theūr and is linked with Siddhaṭek; his descendants at Chinchwad long managed several of the temples. Read '+GP+'.','<b>The Peshwas.</b> Gaṇeśa was the family deity of the Peshwas of Pune. In the 18th century they gave land, money and new halls; Chimājī Appā gilded Ojhar’s dome, and Mādhavrāo I died at Theūr.','<b>Today.</b> Several temples are administered by the Chinchwad Devasthān Trust; the others by local trusts and families.'],[('z','The Peshwas built them all?'),('b','They rebuilt and endowed most, Zappy. The images and stories are older.')],'Saints first, <b>kings after</b>.'),
 reading('moraya','MORAYA GOSĀVĪ','The saint behind the circuit',svg(560,170,'A saint walking between two temples on a road',f'<rect width="560" height="170" fill="#fde9c8"/>'+g(110,150,.9,palace())+g(450,150,.9,palace())+'<path d="M150 150 L410 150" stroke="#b08a5a" stroke-width="6" stroke-dasharray="10 8"/>'+g(280,150,1.2,sage())),['<b>Who.</b> A Gāṇapatya saint, usually placed in the 16th–17th centuries, who settled at Chinchwad near Pune and took samādhi there.','<b>Morgaon.</b> He worshipped Mayūreśvara at Morgaon and walked there from Chinchwad regularly, by tradition stopping at Theūr on the way.','<b>His line.</b> His descendants, the Devs of Chinchwad, were honoured as living forms of Gaṇeśa and managed the finances of several Aṣṭavināyaka temples.','<b>The name.</b> The festival cry <b>“Gaṇapati Bappā Moraya!”</b> is often said to carry his name. (Popular tradition.)'],[('z','So “Moraya” is a saint?'),('b','So the tradition says, Zappy. Every Caturthī crowd shouts his name.')],'Gaṇapati Bappā <b>Moraya</b>.'),
 reading('yatra','MAKING THE YĀTRĀ','How the pilgrimage is done',svg(560,170,'A family in a car on a winding road past hills and temples',f'<rect width="560" height="170" fill="#e3f5e9"/>'+'<path d="M0 140 q140 -60 280 0 t280 0" fill="none" stroke="#7a6a5a" stroke-width="14"/>'+g(120,110,.7,palace())+g(440,110,.7,palace())+g(280,150,1,person('#c0392b'))),['<b>The order.</b> Begin at Morgaon, go round the eight in sequence, and return to Morgaon to close the circle. Many families do it in about three days by road.','<b>The customs.</b> A bath and a simple meal, modakas or laḍḍus as offerings, dūrvā grass, and the āratī “Sukhakartā Duḥkhahartā” at each temple.','<b>The days.</b> Saṅkaṣṭī and Aṅgārakī, Māghī Gaṇeśa Jayantī and Bhādrapada Caturthī draw huge crowds; quieter days are kinder for a first visit.','<b>Practical.</b> Timings, dress rules and queues are set by each temple trust; check locally before you go.'],[('z','Can I do it in one day?'),('b','Some try, Zappy. The tradition is slower. A circle walked in haste isn’t much of a circle.')],'Begin and end <b>at Morgaon</b>.'),
 reading('meaning','WHY A CIRCLE?','The pilgrimage as a teaching',svg(560,160,'A circle of eight lamps around a single Gaṇeśa',f'<rect width="560" height="160" fill="#fff3cf"/>'+''.join(g(280+110*__import__('math').cos(k*0.785),82+55*__import__('math').sin(k*0.785),.6,lamp()) for k in range(8))+g(280,110,.6,ganesha())),['<b>A complete round.</b> Starting and ending at Morgaon makes the journey a circle: what you set out to do is finished. Many read it as Gaṇeśa removing obstacles from beginning to end. (Interpretation.)','<b>Eight forms, one god.</b> Peacock-rider, wish-jewel, boon-giver, lord of obstacles: each temple shows one side of Gaṇeśa.','<b>Devotees as heroes.</b> Ballāḷa the child, Gṛtsamada the sage, Kapila the hermit: the stories put ordinary devotees at the centre.','<b>Gaṇeśa first.</b> Viṣṇu at Siddhaṭek and Śiva at Rāñjaṇgāv both fail until they honour him. The whole circuit says: begin with Gaṇeśa.'],[('z','Even Śiva had to remember Gaṇeśa?'),('b','In the story, Zappy. That’s why we start everything with him.')],'Begin with <b>Gaṇeśa</b>.'),
 end(i,['<b>What.</b> Eight Gaṇeśa temples in a ring round Pune.','<b>Order.</b> Morgaon, Siddhaṭek, Pālī, Mahaḍ, Theūr, Leṇyādri, Ojhar, Rāñjaṇgāv, Morgaon.','<b>Images.</b> All believed svayambhū; one with a right-turned trunk.','<b>People.</b> Moraya Gosāvī and the Peshwas shaped the circuit.','<b>Lesson.</b> Every beginning starts with Gaṇeśa.'],'Begin the circle: '+L('/ganesha/temples/morgaon/','Morgaon')+'.','The Aṣṭavināyaka'),
 sources([SRC_ASH],'the ages of the temples (mostly 18th-century buildings; earlier dates are traditional); the link between Moraya Gosāvī and “Gaṇapati Bappā Moraya” (popular tradition); travel times and temple arrangements (vary).','Study notes on the Aṣṭavināyaka circuit.')]
build(i,'AṢṬAVINĀYAKA · THE OVERVIEW · EIGHT GAṆEŚAS',COV,'The ring round Pune','The <b>order</b> and the <b>map</b>, the <b>svayambhū</b> images, the eight <b>legends</b>, Moraya Gosāvī and the Peshwas, and how the <b>yātrā</b> is made.','The Aṣṭavināyaka explained: the eight Gaṇeśa temples round Pune in order, the map, the self-manifested images, the eight legends, Moraya Gosāvī and the Peshwas, and how the pilgrimage is made.',pp)
print('ash',len(pp)+2)

